command:
sudo -n python3 - <<'ANTRIEB_SHADOW_CHECK'
users = {'mira', 'niko', 'sana'}
with open('/var/tmp/[REDACTED]/records/shadow.src', 'r') as f:
    for line in f:
        fields = line.rstrip('\n').split(':')
        if fields[0] not in users:
            continue
        value = fields[1]
        probe = value.lstrip('!')
        if probe.startswith('$6$'):
            algorithm = 'sha512crypt'
        elif probe.startswith('$5$'):
            algorithm = 'sha256crypt'
        elif probe.startswith('$1$'):
            algorithm = 'md5crypt'
        else:
            algorithm = 'other'
        state = 'locked' if value.startswith(('!', '*')) else 'set'
        print('shadow_snapshot user=%s algorithm=%s state=%s hash_chars=%d last=%s min=%s max=%s warn=%s inactive=%s expire=%s reserved=%s' % (fields[0], algorithm, state, len(value), fields[2], fields[3], fields[4], fields[5], fields[6], fields[7], fields[8]))
ANTRIEB_SHADOW_CHECK

